      const issues = N.deployIssues(c); if (issues.some((i) => i.level === 'block')) throw new Error('Blocking issues: ' + issues.filter((i) => i.level === 'block').map((i) => i.msg).join('; '));
      const date = v.datetime.slice(0, 10);
      N.db.save('crew', { id: c.id, status: 'Onboard', vesselId: v.vesselId, rank: v.rank, signedOn: date, hasContract: true, history: (c.history || []).concat([{ status: 'Onboard', ts: new Date().toISOString(), user: N.user().name, note: `Signed on ${N.vesselName(v.vesselId)} at ${v.port}` }]) });
      if (v.contract === 'NEW') N.db.save('contracts', { ref: N.db.nextRef('CT', 'contracts'), crewId: c.id, vesselId: v.vesselId, rank: v.rank, start: date, end: N.addDays(date, 180), wage: c.fixedSalary, currency: 'USD', type: 'Fixed-term Contract', status: 'Active' });
      const ves = N.db.get('vessels', v.vesselId);
