      N.db.where('seaService', (s) => s.crewId === c.id && !s.signOff).forEach((s) => N.db.save('seaService', { id: s.id, signOff: date, voyageRef: v.voyage || s.voyageRef }, { silent: true }));
      N.db.where('employment', (s) => s.crewId === c.id && s.status === 'Active').forEach((s) => N.db.save('employment', { id: s.id, end: date, status: 'Completed' }, { silent: true }));
      N.db.where('contracts', (s) => s.crewId === c.id && s.status === 'Active').forEach((s) => N.db.save('contracts', { id: s.id, status: 'Completed', end: date }, { silent: true }));
